<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $user = \App\Models\User::whereNotNull("shop_id")->first(); \Illuminate\Support\Facades\Auth::login($user); $reporting = app(\App\Services\ReportingService::class); try { $res = $reporting->getDashboardAnalytics($user->shop_id); echo json_encode($res, JSON_PRETTY_PRINT); } catch (\Exception $e) { echo "ERROR: " . $e->getMessage(); }
